// =============================================
// CONFIGURATION — Edit your values here
// Then click 'Execute Workflow' to save them
// =============================================

const config = {
  // === Bybit API ===
  BYBIT_API_KEY: 'wS5MT4IqmNYxjLuBlP',
  BYBIT_API_SECRET: 'ZmwhvqOx42QzLQ54tMzaUGScr9cSxLU8XklW',
  BYBIT_TESTNET: 'true',  // 'true' for testnet, 'false' for mainnet

  // === OpenRouter API (Claude via OpenRouter) ===
  OPENROUTER_API_KEY: 'YOUR_OPENROUTER_API_KEY',
  OPENROUTER_MODEL: 'anthropic/claude-sonnet-4-20250514',

  // === Telegram ===
  TELEGRAM_CHAT_ID: '543663073',

  // === Trading Parameters ===
  MAX_RISK_PER_TRADE: '1',
  MAX_DAILY_LOSS: '3',
  MAX_OPEN_POSITIONS: '3',
  MIN_RISK_REWARD: '3',
  MIN_CONFIDENCE: '75',
  MIN_VOLUME_24H: '50000000',

  // === n8n Webhook URL ===
  WEBHOOK_URL: 'https://YOUR-N8N-URL.example.com/'
};

// Save to global static data (shared across all workflows)
const store = $getWorkflowStaticData('global');
Object.assign(store, config);
store._configUpdatedAt = new Date().toISOString();

return [{ json: { message: 'Config saved!', config: { ...config, BYBIT_API_SECRET: '***', OPENROUTER_API_KEY: '***' } } }];

// Verify saved config
const store = $getWorkflowStaticData('global');

const required = [
  'BYBIT_API_KEY', 'BYBIT_API_SECRET', 'OPENROUTER_API_KEY',
  'TELEGRAM_CHAT_ID', 'WEBHOOK_URL'
];

const missing = required.filter(k => !store[k] || store[k].startsWith('YOUR_'));

let status = '';
if (missing.length > 0) {
  status = '❌ НЕ НАСТРОЕНО! Замените значения YOUR_... на реальные:\n' + missing.join(', ');
} else {
  status = '✅ Все ключи настроены!';
}

return [{
  json: {
    status,
    BYBIT_TESTNET: store.BYBIT_TESTNET,
    OPENROUTER_MODEL: store.OPENROUTER_MODEL,
    MAX_RISK_PER_TRADE: store.MAX_RISK_PER_TRADE,
    MAX_DAILY_LOSS: store.MAX_DAILY_LOSS,
    MAX_OPEN_POSITIONS: store.MAX_OPEN_POSITIONS,
    MIN_RISK_REWARD: store.MIN_RISK_REWARD,
    MIN_CONFIDENCE: store.MIN_CONFIDENCE,
    _configUpdatedAt: store._configUpdatedAt
  }
}];
